// черновик не создаётся. Дополняет 1.1–1.2 (@data), которые проверяют подпись на живом шаге 5 только с QA_REAL_WRITE=1.
import { test, expect, APIRequestContext } from '@playwright/test';

/** Все JS-чанки текущего релиза: главный скрипт из HTML + имена assets/*.js, упомянутые в нём. */
async function loadChunks(request: APIRequestContext): Promise<Map<string, string>> {
  const html = await (await request.get('/addbusiness')).text();
  const main = html.match(/\/assets\/[A-Za-z0-9_.-]+\.js/)?.[0];
  expect(main, 'в HTML есть главный скрипт /assets/*.js').toBeTruthy();
  const mainRes = await request.get(main!);
  expect(mainRes.status(), `${main} — 200`).toBe(200);
  const mainJs = await mainRes.text();
  const names = [...new Set(mainJs.match(/assets\/[A-Za-z0-9_.-]+\.js/g) ?? [])];
  const chunks = new Map<string, string>([[main!, mainJs]]);
  for (const n of names) {
    const r = await request.get('/' + n);
    if (r.ok()) chunks.set('/' + n, await r.text());
  }
  return chunks;
}

test.describe('Публикация бизнеса — шаг 5: подпись поля счёта в коде релиза', () => {
  test('Подпись поля #invoice-name — «שם לחשבונית», без «מס» и без «(לא חובה)» #2e5dd0 #8bea2a @desktop @prod-safe', async ({ request }) => {
    const chunks = await loadChunks(request);
    const withField = [...chunks].filter(([, js]) => js.includes('id:"invoice-name"'));
    expect(withField.length, 'поле id="invoice-name" есть в коде релиза (шаг 5)').toBeGreaterThan(0);
    for (const [name, js] of withField) {
      expect(js, `${name}: подпись «שם לחשבונית» (#2e5dd0)`).toContain('children:"שם לחשבונית"');
      expect(js, `${name}: placeholder не изменился (#8bea2a)`).toContain('השם שיופיע בחשבונית');
    }
    for (const [name, js] of chunks) {
      expect(js.includes('שם לחשבונית מס'), `${name}: старой подписи «שם לחשבונית מס» нет (#2e5dd0)`).toBe(false);
    }
  });
});
